namespace {

inline uint16_t swapBytes(uint16_t v) {
    return (v << 8) | (v >> 8);
}

inline bool memRead(const Signals *s) {
    return s->memReq() && s->read();
}

// Data kinds, as BUS_BYTES[] counts them: memory read, write; I/O read, write.
enum BusKind : int_fast8_t {
    NOT_DATA = -1,
    MEM_READ,
    MEM_WRITE,
    IO_READ,
    IO_WRITE
};

BusKind busKindOf(const Signals *s) {
    if (s->memReq())
        return s->read() ? MEM_READ : MEM_WRITE;
    if (s->intAck() || !s->any())
        return NOT_DATA;
    return s->write() ? IO_WRITE : IO_READ;  // RETI's I/O read too
}

inline uint_fast8_t bytesOf(const Signals *s) {
    return s->wordAccess() ? 2 : 1;
}

inline bool isFetch(const Signals *s, uint32_t fetch) {
    return memRead(s) && s->addr == fetch;
}

// Whether the read |s| brought the byte at |addr|.
inline bool covers(const Signals *s, uint32_t addr) {
    const auto even = ~UINT32_C(1);
    return s->addr == addr ||
           (s->wordAccess() && (s->addr & even) == (addr & even));
}

// Where the fetch stream goes on after |s|.
inline uint32_t advance(const Signals *s) {
    return s->wordAccess() ? (s->addr & ~UINT32_C(1)) + 2 : s->addr + 1;
}

constexpr char BUS_KIND[] = "RWrw";

}  // namespace

bool InstZ380::decode(uint32_t pc, Decoded &inst) const {
    const auto &m = *_mems;
    auto b0 = m.read_byte(pc);
    auto b1 = m.read_byte(pc + 1);
    inst.addr = pc;
    inst.extension = 0;
    inst.ddirWord = 0;
    inst.ddirLength = 0;
    // DDIR decoder directives: DD C0-C3 W, IB W, IW W, IB; FD C0-C3 LW,
    // IB LW, IW LW, IW.
    if ((b0 == 0xDD || b0 == 0xFD) && (b1 & 0xFC) == 0xC0) {
        const auto d = b1 & 3;
        inst.extension = d == 3 ? (b0 == 0xDD ? 1 : 2) : d;
        inst.ddirWord = d == 3 ? 0 : (b0 == 0xDD ? 1 : 2);
        inst.ddirLength = 2;
        b0 = m.read_byte(pc + 2);
        b1 = m.read_byte(pc + 3);
    }
    const auto base = pc + inst.ddirLength;
    Opcode opcode;
    inst.opcodeLength = 2;
    if (b0 == 0xCB) {
        opcode = PAGECB_TABLE[b1];
    } else if (b0 == 0xED) {
        opcode = b1 == 0xCB ? PAGEEDCB_TABLE[m.read_byte(base + 2)]
                            : PAGEED_TABLE[b1];
    } else if (b0 == 0xDD || b0 == 0xFD) {
        if (b1 == 0xCB) {
            // the displacement, widened by IB or IW, before the opcode
            const auto op = m.read_byte(base + 3 + inst.extension);
            opcode = b0 == 0xDD ? PAGEDDCB_TABLE[op] : PAGEFDCB_TABLE[op];
        } else {
            opcode = b0 == 0xDD ? PAGEDD_TABLE[b1] : PAGEFD_TABLE[b1];
        }
    } else {
        opcode = PAGE00_TABLE[b0];
        inst.opcodeLength = 1;
    }
    if (opcode.length() == 0)
        return false;
    inst.flow = opcode.flow();
    inst.conditional = opcode.conditional();
    inst.index = opcode.index();
    if (inst.ddirLength && !opcode.widened()) {
        if (inst.flow == F_REPEAT ||
                BUS_BYTES[inst.index].longWord == BusBytes::AS_TAKEN) {
            // one the directive does not affect: two bytes of its own
            inst.length = 2;
            inst.flow = F_NONE;
            inst.conditional = false;
            inst.index = 0;  // moves nothing
            inst.extension = inst.ddirWord = inst.ddirLength = 0;
            return true;
        }
        inst.extension = 0;
    }
    inst.length = inst.ddirLength + opcode.length() + inst.extension;
    return true;
}

uint32_t InstZ380::transferTarget(const Decoded &inst) const {
    const auto mask = _xm ? UINT32_MAX : UINT32_C(0xFFFF);
    const auto end = inst.addr + inst.length;
    // the instruction's last |n| bytes, little endian
    auto operand = [&](uint_fast8_t n) {
        uint32_t v = 0;
        for (auto i = 0u; i < n; ++i)
            v |= static_cast<uint32_t>(_mems->read_byte(end - n + i))
                 << (8 * i);
        return v;
    };
    switch (inst.flow) {
    case F_ABS:
        return operand(2 + inst.extension) & mask;
    case F_REL: {
        const auto n = inst.length - inst.ddirLength - inst.opcodeLength;
        auto v = operand(n);
        const auto sign = UINT32_C(1) << (8 * n - 1);
        v = (v ^ sign) - sign;  // sign extend
        return (end + v) & mask;
    }
    case F_RST:
        return _mems->read_byte(inst.addr + inst.ddirLength) & 0x38;
    default:
        return 0;  // TRAP; IND has none
    }
}

void InstZ380::busBytes(
        const Decoded &inst, bool taken, uint8_t bytes[4]) const {
    const auto &d = BUS_BYTES[inst.index];
    const auto lw = inst.ddirWord == 2 || (inst.ddirWord == 0 && _lw);
    for (auto k = 0u; k < 4; ++k) {
        if (inst.conditional && !taken) {
            bytes[k] = BusBytes::get(d.notTaken, k);
            continue;
        }
        const auto words =
                (lw && d.longWord != BusBytes::AS_TAKEN) ? d.longWord : d.taken;
        auto n = BusBytes::get(words, k);
        if (_xm && d.extended != BusBytes::AS_TAKEN)
            n += BusBytes::get(d.extended, k) - BusBytes::get(d.taken, k);
        bytes[k] = n;
    }
}

void InstZ380::assign(uint_fast8_t i, bool data) {
    const auto s = _begin->next(i);
    _owner[i] = _steps - 1;
    if (data) {
        s->markOperand();
    } else if (!s->fetch()) {
        s->markByte();
    }
}

// A new instruction at |addr|, its first byte brought by the latest fetch
// before cycle |i| that covers it.
bool InstZ380::addStep(uint32_t addr, bool interrupt, uint_fast8_t i) {
    if (_steps >= MAX_STEPS)
        return false;
    auto &step = _step[_steps++];
    step.addr = addr;
    step.interrupt = interrupt;
    step.taken = interrupt;
    step.fetchAt = i;  // none
    while (!interrupt && i-- > 0) {
        const auto s = _begin->next(i);
        if (memRead(s) && !s->isOperand() && covers(s, addr)) {
            step.fetchAt = i;
            break;
        }
    }
    return true;
}

// The ring ends with the CPU at |pc|; it stops at _stop, which may be an
// instruction the queue already holds, those decoded after it not run.
bool InstZ380::endsAt(uint32_t pc) {
    if (pc == _stop)
        return true;
    for (auto n = _steps; n-- > 0;) {
        bool busy = _step[n].interrupt;
        for (auto i = 0u; i < _size && !busy; ++i)
            busy = _owner[i] == n && _begin->next(i)->isOperand();
        if (busy)
            break;
        if (_step[n].addr == _stop) {
            for (auto i = 0u; i < _size; ++i) {
                if (_owner[i] != NOBODY && _owner[i] != LEAD &&
                        _owner[i] >= n)
                    _owner[i] = n ? n - 1 : NOBODY;
            }
            _steps = n;
            return true;
        }
    }
    TRACE("    ring ends at %X, stop at %X\n", pc, _stop);
    return false;
}

// An acknowledged interrupt, an NMI or a trap taken at |pc|, or wherever
// the push says if |anyPc|: the PC pushed and the vector fetched, in
// either order.
bool InstZ380::interruptAt(
        uint_fast8_t &i0, uint32_t &pc, uint32_t &fetch0, bool anyPc) {
    auto i = i0;
    auto fetch = fetch0;
    while (i < _size && isFetch(_begin->next(i), fetch))
        fetch = advance(_begin->next(i++));
    if (i >= _size)
        return false;
    auto s = _begin->next(i);
    bool known = false;
    uint32_t target = 0;
    if (s->intAck()) {
        const auto v = s->data & 0xFF;
        if ((v & 0xC7) == 0xC7) {  // mode 0: a RST
            known = true;
            target = v & 0x38;
        }
        ++i;
    } else if (!s->memReq() || s->read()) {
        return false;
    }
    uint_fast8_t left = _xm ? 4 : 2;
    uint_fast8_t pushes = 0;
    const Signals *pushed = nullptr;
    const Signals *vector = nullptr;
    for (; i < _size && (left > 0 || vector == nullptr); ++i) {
        s = _begin->next(i);
        if (s->memReq() && s->write() && left >= bytesOf(s)) {
            left -= bytesOf(s);
            pushed = s;
            ++pushes;
        } else if (memRead(s) && vector == nullptr &&
                   (known ? s->addr == target
                          : (s->addr == ORG_RESET || s->addr == ORG_RST38 ||
                                    s->addr == ORG_NMI))) {
            vector = s;
            fetch = advance(s);
        } else if (isFetch(s, fetch)) {
            fetch = advance(s);
        } else {
            return false;
        }
    }
    if (vector == nullptr || left > 0)
        return false;
    // but for a trap, the PC pushed is the one interrupted
    if (!anyPc && vector->addr != ORG_RESET && pushes == 1 &&
            swapBytes(pushed->data) != static_cast<uint16_t>(pc))
        return false;
    if (!addStep(vector->addr, true, i))
        return false;
    for (auto j = i0; j < i; ++j) {
        const auto t = _begin->next(j);
        assign(j, t->intAck() || (t->memReq() && t->write()));
    }
    i0 = i;
    pc = vector->addr;
    fetch0 = fetch;
    return true;
}

// Its data cycles and, if |taken|, its target's fetch, in any order; the
// sequential fetches go on meanwhile.
InstZ380::Result InstZ380::execute(uint_fast8_t &i, uint32_t &pc,
        uint32_t &fetch, const Decoded &inst, bool taken) {
    uint8_t need[4];
    busBytes(inst, taken, need);
    const auto cls = inst.flow;
    const auto known = cls != F_IND;
    const auto target = taken ? transferTarget(inst) : 0;
    auto pending = taken;
    auto next = pc + inst.length;
    // A word split by its alignment is consecutive bytes: an instruction's
    // memory reads, and its writes, are contiguous.
    uint32_t after[2];
    bool seen[2] = {false, false};
    const auto first = _steps == 0;
    auto claimed = false;
    uint_fast8_t lead = 0;
    if (!addStep(pc, false, i))
        return FAILED;
    _step[_steps - 1].taken = taken;
    auto busy = [&]() {
        return pending || need[0] || need[1] || need[2] || need[3];
    };
    for (; busy(); ++i) {
        if (i >= _size) {
            // ended inside it: still the instruction being run
            if (pc == _stop || endsAt(pending && known ? target : next))
                return ENDED;
            return FAILED;
        }
        if (--_budget == 0)
            return FAILED;
        const auto s = _begin->next(i);
        const auto k = busKindOf(s);
        // an interrupt taken before the target's fetch pushes the target
        if (pending && !(need[0] | need[1] | need[2] | need[3]) &&
                (s->intAck() || (s->memReq() && s->write()))) {
            auto at = known ? target : pc;
            if (interruptAt(i, at, fetch, !known)) {
                pc = at;
                return i >= _size ? (endsAt(pc) ? ENDED : FAILED) : NEXT;
            }
        }
        if (pending && known && memRead(s) && s->addr == target) {
            // a target the queue was about to fetch anyway is still one
            pending = false;
            next = s->addr;
            fetch = advance(s);
            assign(i, false);
        } else if (isFetch(s, fetch)) {
            fetch = advance(s);
            assign(i, false);
        } else if (k != NOT_DATA && need[k] >= bytesOf(s) &&
                   (k > MEM_WRITE || !seen[k] || s->addr == after[k])) {
            need[k] -= bytesOf(s);
            if (k <= MEM_WRITE) {
                after[k] = advance(s);
                seen[k] = true;
            }
            assign(i, true);
            claimed = true;
        } else if (pending && !known && memRead(s)) {
            pending = false;
            next = s->addr;
            fetch = advance(s);
            assign(i, false);
        } else if (first && !claimed && lead < LEAD_MAX && k != NOT_DATA) {
            ++lead;  // an earlier instruction's
            _owner[i] = LEAD;
        } else {
            TRACE("    %c%X not wanted by %X\n",
                    k == NOT_DATA ? '?' : BUS_KIND[k], s->addr, pc);
            return FAILED;
        }
    }
    if (cls == F_STOP) {
        while (i < _size && _begin->next(i)->halt())
            assign(i++, true);
    }
    // a pipeline flush fetches the next instruction, or the target, again
    if (i < _size) {
        const auto s = _begin->next(i);
        if (memRead(s) && s->addr != fetch &&
                (s->addr == next || s->addr == (next & ~UINT32_C(1)))) {
            fetch = advance(s);
            assign(i++, false);
        }
    }
    pc = next;
    if (i >= _size)
        return endsAt(pc) ? ENDED : FAILED;
    return NEXT;
}

// Iterations while each transfer steps from its previous one.
void InstZ380::repeat(uint_fast8_t &i, uint32_t &fetch, const Decoded &inst) {
    const auto &b = REPEATS[inst.index];
    uint32_t last[2];
    bool seen[2] = {false, false};
    uint_fast8_t j = 0;
    for (; i < _size; ++i) {
        const auto s = _begin->next(i);
        if (isFetch(s, fetch)) {
            fetch = advance(s);
            assign(i, false);
            continue;
        }
        const auto k = busKindOf(s);
        if (k == NOT_DATA || BUS_KIND[k] != b.kind[j])
            break;
        if (seen[j] && b.step[j] != Repeat::ANY_STEP &&
                s->addr != last[j] + static_cast<int32_t>(b.step[j]))
            break;
        last[j] = s->addr;
        seen[j] = true;
        assign(i, true);
        j = (j + 1) % b.transfers;
    }
}

// The walk from cycle |i|, a fetch holding the instruction at |addr|.
bool InstZ380::walkFrom(uint_fast8_t i, uint32_t addr) {
    for (auto j = 0u; j < _size; ++j) {
        _owner[j] = NOBODY;
        const auto s = _begin->next(j);
        if (!s->halt())
            s->clearMark();
    }
    _steps = 0;
    _backtracks = 0;
    auto pc = addr;
    auto fetch = advance(_begin->next(i));
    _begin->next(i)->markByte();
    _owner[i] = 0;  // the first instruction's
    ++i;
    Decoded inst;
    bool taken;
    Result result;
    uint_fast8_t lead;
    while (true) {
        if (--_budget == 0)
            return false;
        interruptAt(i, pc, fetch);
        if (!decode(pc, inst)) {
            TRACE("    undecodable at %X\n", pc);
            goto backtrack;
        }
        // its bytes
        lead = 0;
        while (fetch < pc + inst.length) {
            if (i >= _size) {
                if (!addStep(pc, false, i))
                    return false;
                if (endsAt(pc))
                    return true;
                goto backtrack;
            }
            const auto s = _begin->next(i);
            if (!isFetch(s, fetch) && _steps == 0 && lead < LEAD_MAX &&
                    busKindOf(s) != NOT_DATA) {
                ++lead;  // an earlier instruction's
                _owner[i] = LEAD;
                ++i;
                continue;
            }
            if (!isFetch(s, fetch)) {
                TRACE("    fetch %X expected at %X\n", fetch, pc);
                goto backtrack;
            }
            fetch = advance(s);
            _owner[i] = _steps;  // the instruction about to be added
            s->markByte();
            ++i;
        }
        if ((inst.flow) == F_REPEAT) {
            if (!addStep(pc, false, i))
                return false;
            repeat(i, fetch, inst);
            pc += inst.length;
            if (i >= _size) {
                if (endsAt(pc))
                    return true;
                goto backtrack;
            }
            continue;
        }
        if (inst.conditional) {
            if (_backtracks >= MAX_BACKTRACKS)
                return false;
            _backtrack[_backtracks++] = Backtrack{pc, fetch,
                    static_cast<uint16_t>(_steps), static_cast<uint8_t>(i)};
            taken = true;
        } else {
            const auto cls = inst.flow;
            taken = cls == F_ABS || cls == F_REL || cls == F_IND ||
                    cls == F_RST || cls == F_TRAP;
        }
    run:
        result = execute(i, pc, fetch, inst, taken);
        if (result == ENDED)
            return true;
        if (result == NEXT)
            continue;
    backtrack:
        if (_backtracks == 0)
            return false;
        {
            const auto &c = _backtrack[--_backtracks];
            for (auto j = c.i; j < _size; ++j) {
                _owner[j] = NOBODY;
                const auto s = _begin->next(j);
                if (!s->halt())
                    s->clearMark();
            }
            i = c.i;
            _steps = c.steps;
            pc = c.pc;
            fetch = c.fetch;
        }
        decode(pc, inst);
        taken = false;
        goto run;
    }
}

// A ring that begins inside an instruction can be walked from a byte of
// it: drop the instructions ahead of the first that moved data,
// transferred or was an interrupt, which nothing confirms.
void InstZ380::dropUnconfirmed() {
    uint_fast16_t n = 0;
    for (; n < _steps && !_step[n].taken; ++n) {
        bool data = false;
        for (auto i = 0u; i < _size && !data; ++i)
            data = _owner[i] == n && _begin->next(i)->isOperand();
        if (data)
            break;
    }
    if (n == 0 || n == _steps)
        return;
    for (auto i = 0u; i < _size; ++i) {
        if (_owner[i] == NOBODY || _owner[i] == LEAD)
            continue;
        _owner[i] = _owner[i] < n ? LEAD : _owner[i] - n;
    }
    for (auto k = n; k < _steps; ++k)
        _step[k - n] = _step[k];
    _steps -= n;
}

bool InstZ380::walk(Signals *begin, const Signals *end, const Memory &mems,
        uint32_t pc, bool xm, bool lw) {
    _begin = begin;
    _size = begin->diff(end);
    _mems = &mems;
    _stop = pc;
    _xm = xm;
    _lw = lw;
    _budget = 200000;
    _start = nullptr;
    for (auto i = 0u; i < _size; ++i) {
        const auto s = begin->next(i);
        if (!memRead(s))
            continue;
        for (auto a = 0u; a < (s->wordAccess() ? 2u : 1u); ++a) {
            TRACE("  from %u at %X\n", i, s->addr + a);
            if (walkFrom(i, s->addr + a)) {
                _start = s;
                dropUnconfirmed();
                for (auto n = 0u; n < _steps; ++n) {
                    if (_step[n].fetchAt < _size)
                        begin->next(_step[n].fetchAt)->markFetch();
                }
                return true;
            }
            if (_budget == 0)
                break;
        }
        if (_budget == 0)
            break;
    }
    for (auto i = 0u; i < _size; ++i) {
        _owner[i] = NOBODY;
        if (!begin->next(i)->halt())
            begin->next(i)->clearMark();
    }
    _steps = 0;
    return false;
}

